import{describe,it,expect,beforeEach}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url)),tripDataCode=readFileSync(resolve(__dirname,"../../trip-data.js"),"utf-8"),getTripData=new Function(tripDataCode+"\nreturn { tripDestinations };"),{tripDestinations:tripDestinations}=getTripData();globalThis.tripDestinations=tripDestinations;const engineCode=readFileSync(resolve(__dirname,"../../frontend/js-modules/destination-comparison-engine.js"),"utf-8");new Function(engineCode)();const DestinationComparison=globalThis.DestinationComparison;describe("DestinationComparison: derived attributes",()=>{const e=tripDestinations.find(e=>"agra"===e.id),t=tripDestinations.find(e=>"manali"===e.id),i=tripDestinations.find(e=>"jaisalmer"===e.id);it("estimates climate from category, preferring the most climate-specific category",()=>{expect(DestinationComparison.estimateClimate(i)).toMatch(/hot|dry/i),expect(DestinationComparison.estimateClimate(t)).toMatch(/cool|cold/i)}),it("gives adventure-tagged, mountain destinations a higher adventure level than a historical city",()=>{expect(DestinationComparison.estimateAdventureLevel(t)).toBeGreaterThan(DestinationComparison.estimateAdventureLevel(e))}),it("keeps every derived score within its documented 1-5 range",()=>{tripDestinations.forEach(e=>{expect(DestinationComparison.estimateAdventureLevel(e)).toBeGreaterThanOrEqual(1),expect(DestinationComparison.estimateAdventureLevel(e)).toBeLessThanOrEqual(5),expect(DestinationComparison.estimateFamilyFriendliness(e)).toBeGreaterThanOrEqual(1),expect(DestinationComparison.estimateFamilyFriendliness(e)).toBeLessThanOrEqual(5),expect(DestinationComparison.estimateAccessibility(e)).toBeGreaterThanOrEqual(1),expect(DestinationComparison.estimateAccessibility(e)).toBeLessThanOrEqual(5)})}),it("finds nearby destinations within the search radius, nearest first",()=>{const t=DestinationComparison.findNearbyDestinations(e,tripDestinations);for(let e=1;e<t.length;e++)expect(t[e-1].distanceKm).toBeLessThanOrEqual(t[e].distanceKm);t.forEach(e=>expect(e.distanceKm).toBeLessThanOrEqual(200)),expect(t.some(t=>t.id===e.id)).toBe(!1)})}),describe("DestinationComparison: compareDestinations",()=>{it("compares 1 to 4 destinations and includes every required attribute",()=>{const e=DestinationComparison.compareDestinations(["agra","jaipur","manali","goa"],tripDestinations,"mid");expect(e.destinations).toHaveLength(4),e.destinations.forEach(e=>{expect(e).toHaveProperty("bestTimeToVisit"),expect(e).toHaveProperty("estimatedBudgetPerDay"),expect(e).toHaveProperty("popularAttractions"),expect(e).toHaveProperty("weather"),expect(e).toHaveProperty("idealTripDuration"),expect(e).toHaveProperty("adventureLevel"),expect(e).toHaveProperty("familyFriendliness"),expect(e).toHaveProperty("accessibility"),expect(e).toHaveProperty("nearbyDestinations"),expect(e).toHaveProperty("userRating")})}),it("rejects more than four destinations",()=>{expect(()=>DestinationComparison.compareDestinations(["agra","jaipur","manali","goa","shimla"],tripDestinations)).toThrow(/up to 4/)}),it("rejects an empty selection",()=>{expect(()=>DestinationComparison.compareDestinations([],tripDestinations)).toThrow(/at least one/i)}),it("rejects an unknown destination id",()=>{expect(()=>DestinationComparison.compareDestinations(["not-a-real-place"],tripDestinations)).toThrow(/unknown destination/i)}),it("reflects the requested cost tier in estimatedBudgetPerDay",()=>{const e=DestinationComparison.compareDestinations(["agra"],tripDestinations,"budget").destinations[0],t=DestinationComparison.compareDestinations(["agra"],tripDestinations,"luxury").destinations[0];expect(e.estimatedBudgetPerDay).toBeLessThan(t.estimatedBudgetPerDay)}),it("updates dynamically — recomparing with a different destination set changes the result, not a cached one",()=>{const e=DestinationComparison.compareDestinations(["agra"],tripDestinations),t=DestinationComparison.compareDestinations(["manali"],tripDestinations);expect(e.destinations[0].name).not.toBe(t.destinations[0].name)})}),describe("DestinationComparison: getRecommendation",()=>{it("recommends the cheaper destination when budget is weighted heavily and nothing else is",()=>{const e=DestinationComparison.compareDestinations(["udaipur","haridwar"],tripDestinations,"mid"),t=DestinationComparison.getRecommendation(e,{budgetWeight:5,adventureWeight:0,familyWeight:0,accessibilityWeight:0});expect(t.winner.id).toBe("haridwar")}),it("recommends the more adventurous destination when adventure is weighted heavily and nothing else is",()=>{const e=DestinationComparison.compareDestinations(["agra","manali"],tripDestinations,"mid"),t=DestinationComparison.getRecommendation(e,{budgetWeight:0,adventureWeight:5,familyWeight:0,accessibilityWeight:0});expect(t.winner.id).toBe("manali")}),it("produces a human-readable explanation naming the winning destination",()=>{const e=DestinationComparison.compareDestinations(["jaipur","shimla"],tripDestinations,"mid"),t=DestinationComparison.getRecommendation(e,{familyWeight:4});expect(t.explanation).toContain(t.winner.name)}),it("penalizes destinations that need longer than the stated trip window",()=>{const e=DestinationComparison.compareDestinations(["haridwar","lakshadweep"],tripDestinations,"mid"),t=DestinationComparison.getRecommendation(e,{maxDays:1}).ranked.find(e=>"lakshadweep"===e.id);expect(t.reasons.join(" ")).toMatch(/longer than your window/)}),it("handles an empty comparison gracefully instead of throwing",()=>{const e=DestinationComparison.getRecommendation({costTier:"mid",destinations:[]},{});expect(e.winner).toBeUndefined(),expect(e.explanation).toMatch(/add destinations/i)})}),describe("DestinationComparison: export",()=>{const e=DestinationComparison.compareDestinations(["agra","jaipur"],tripDestinations,"mid"),t=DestinationComparison.getRecommendation(e,{budgetWeight:3});it("exportComparisonText includes every compared destination and the recommendation",()=>{const i=DestinationComparison.exportComparisonText(e,t);expect(i).toContain("Agra"),expect(i).toContain("Jaipur"),expect(i).toContain(t.winner.name)}),it("exportComparisonJSON produces valid, parseable JSON with matching destination count",()=>{const i=DestinationComparison.exportComparisonJSON(e,t),n=JSON.parse(i);expect(n.destinations).toHaveLength(2),expect(n.recommendation).toContain(t.winner.name)})}),describe("DestinationComparison: saved comparisons (localStorage)",()=>{beforeEach(()=>{localStorage.clear()}),it("starts with no saved comparisons",()=>{expect(DestinationComparison.getSavedComparisons()).toEqual([])}),it("saves a comparison and retrieves it later",()=>{const e=DestinationComparison.saveComparison("Rajasthan trip",["jaipur","jodhpur","udaipur"]),t=DestinationComparison.getSavedComparisons();expect(t).toHaveLength(1),expect(t[0].id).toBe(e.id),expect(t[0].ids).toEqual(["jaipur","jodhpur","udaipur"])}),it("deletes a saved comparison by id",()=>{const e=DestinationComparison.saveComparison("Hills trip",["shimla","manali"]);DestinationComparison.deleteSavedComparison(e.id),expect(DestinationComparison.getSavedComparisons()).toEqual([])})});